def O(context: str, name: str, inputs: list[str], output: str, purity: str = "pure", intent: str | None = None, receipt: str | None = None) -> dict:
    row = {"operation_ref": f"operation.{context}.{name}", "input_types": inputs, "output_type": f"Result<{output},{context.split('.')[-1].title().replace('_', '')}Refusal>", "purity": purity}
