def materialize(spec: dict) -> dict:
    ctx = spec["ctx"]
    effect = "pure_effect_intents" if spec["kind"] == "effect_port" else "pure_no_io"
    return {"library_id":spec["id"],"name":spec["name"],"library_kind":spec["kind"],"semantic_owner_context":f"context.{ctx}","status":"specified","candidate_responsibility":spec["name"].lower(),"effect_boundary":effect,"public_types":spec["types"],"public_traits":[spec["name"].replace(" ","")+"Algebra"],"operation_refs":[op["operation_ref"] for op in spec["ops"]],"operations":spec["ops"],"decision_refs":[f"decision.{ctx}.{d}" for d in DECISIONS[ctx]],"configuration_contracts":[spec["name"].replace(" ","")+"Policy"],"laws":spec["laws"],"invariants":["published editions are immutable","all authority and evidence are exact-subject, edition, purpose, scope and time bound","unknown, absent, refused, failed and completion-unknown remain distinct"],"error_contracts":spec["errors"]+["UnsupportedEdition","InvalidConfiguration","ResourceBudgetExceeded"],"dependencies":spec["deps"],"evidence_refs":spec["evidence"],"oracles":["canonical positive fixtures","negative twins","property laws","state-machine model tests","malformed and boundary corpus","edition migration corpus","two independent differential implementations"],"gaps":["No implementation is qualified; two independent implementations and executed conformance remain required."],"must_not_own":["source or dataset truth","business semantics outside the contract","provider qualification","legal interpretation","unauthorized external effects"],"qualification_required":False}


